const TZ = 'YOUR_CLINIC_TIMEZONE';
function tzDateStr(d, tz, offsetDays = 0) {
  const x = new Date(d);
  x.setUTCDate(x.getUTCDate() + offsetDays);
  return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(x);
}

const now = new Date();
const nowIso = now.toISOString();

// Compute 60/90/180-day cutoffs relative to clinic's local timezone (YYYY-MM-DD strings)
const days60str  = tzDateStr(now, TZ, -60);
const days90str  = tzDateStr(now, TZ, -90);
const days180str = tzDateStr(now, TZ, -180);
const currentMonthKey = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit' }).format(now); // e.g. '2026-04'

// Seasonal promotions — detect current season in clinic's timezone
const tzMonth = parseInt(new Intl.DateTimeFormat('en-US', { timeZone: TZ, month: 'numeric' }).format(now));
const month = tzMonth;
let season, seasonalPromo;
if (month >= 3 && month <= 5) {
  season = 'Spring';
  seasonalPromo = { subject: '🌸 Spring refresh — exclusive offer for you', theme: 'spring', offer: '20% off HydraFacial or Chemical Peel this month — the perfect spring skin reset.', color: '#ec4899' };
} else if (month >= 6 && month <= 8) {
  season = 'Summer';
  seasonalPromo = { subject: '☀️ Summer-ready skin — special offer inside', theme: 'summer', offer: 'Get summer-ready with 15% off laser hair removal or body contouring this month.', color: '#f59e0b' };
} else if (month >= 9 && month <= 11) {
  season = 'Fall';
  seasonalPromo = { subject: '🍂 Fall skin renewal — your exclusive offer', theme: 'fall', offer: 'Fall is the perfect time for deeper treatments. 15% off microneedling or a full Botox touch-up this month.', color: '#b45309' };
} else {
  season = 'New Year';
  seasonalPromo = { subject: '✨ New year, new you — exclusive January offer', theme: 'winter', offer: 'Start the year feeling your best. 20% off any injectable treatment booked this month.', color: '#7c3aed' };
}

return [{ json: { nowIso, days60Str: days60str, days90Str: days90str, days180Str: days180str, currentMonthKey, season, seasonalPromo } }];

const TZ = 'YOUR_CLINIC_TIMEZONE';
function tzDateStr(d, tz) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(d));
}

const clients = $input.all();
const dates   = $('Calculate Dates + Season').first().json;
const sp      = dates.seasonalPromo;
const nowIso  = dates.nowIso;
const currentMonthKey = dates.currentMonthKey;

const lapsed60   = [];
const lapsed90   = [];
const lapsed180  = [];
const seasonal   = [];

for (const item of clients) {
  const c = item.json;
  if (!c['Client Email'] || (c['Opted Out'] || '').toLowerCase() === 'yes') continue;
  if ((c['Status'] || '') === 'New Inquiry') continue;  // Haven't visited yet

  const lastVisit = c['Last Visit Date'] ? new Date(c['Last Visit Date']) : null;
  if (!lastVisit || isNaN(lastVisit)) continue;

  const lastVisitStr = tzDateStr(lastVisit, TZ);
  const totalVisits  = parseInt(c['Total Visits'] || 1);
  const vipStatus    = (c['VIP Status'] || 'Standard').trim();
  const lastPromoMonth = (c['Last Promo Month'] || '').trim();

  const base = {
    clientEmail:  c['Client Email'].trim(),
    clientName:   (c['Client Name'] || 'there').trim(),
    service:      c['Service Interest'] || 'your last treatment',
    totalVisits,
    vipStatus,
    lastVisitStr,
    nowIso,
    currentMonthKey,
    seasonalPromo: sp
  };

  // Lapsed buckets + idempotency: don't re-send if already contacted this month
  if (lastPromoMonth !== currentMonthKey) {
    if (lastVisitStr <= dates.days180Str) {
      lapsed180.push({ ...base, type: 'LAPSED_180' });
    } else if (lastVisitStr <= dates.days90Str) {
      lapsed90.push({ ...base, type: 'LAPSED_90' });
    } else if (lastVisitStr <= dates.days60Str) {
      lapsed60.push({ ...base, type: 'LAPSED_60' });
    } else {
      // Seasonal promo: only clients who visited within the last 60 days
      seasonal.push({ ...base, type: 'SEASONAL' });
    }
  }
}

const allItems = [...lapsed60, ...lapsed90, ...lapsed180, ...seasonal];

if (allItems.length === 0) {
  return [{ json: { type: 'NONE', nowIso } }];
}

return allItems.map(i => ({ json: i }));

