// Parse AI response and merge with the paired segment row.
// Do not use .first() here: monthly retention can process many clients at once.
const aiRaw = $input.first().json;
let segData;
try {
  segData = $('Segment Clients').item.json;
} catch (e) {
  segData = $('Segment Clients').first().json;
}

let ai = null;
try {
  const text = aiRaw?.content?.[0]?.text || '';
  ai = JSON.parse(text);
} catch(e) { ai = null; }

const hasAi = ai && typeof ai.subject === 'string' && typeof ai.personalizedParagraph === 'string';

return [{
  json: {
    ...segData,
    aiUsed:    hasAi,
    aiSubject: hasAi ? ai.subject : null,
    aiParagraph: hasAi ? ai.personalizedParagraph : null
  }
}];

// Gmail can output message metadata. Restore the paired retention item before logging and marking promo sent.
let source;
try {
  source = $('Merge AI + Fallback').item.json;
} catch (e) {
  source = $input.first().json;
}
return [{ json: source }];
